```python
class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end_of_word = False

class SpellChecker:
    def __init__(self):
        self.root = TrieNode()

    def insert_word(self, word):
        current_node = self.root
        for char in word:
            if char not in current_node.children:
                current_node.children[char] = TrieNode()
            current_node = current_node.children[char]
        current_node.is_end_of_word = True

    def build_trie(self, word_list):
        for word in word_list:
            self.insert_word(word)

    def search_word(self, word):
        current_node = self.root
        suggestions = []
        misspelled = False

        for char in word:
            if char in current_node.children:
                current_node = current_node.children[char]
            else:
                misspelled = True
                break

        if misspelled:
            self._suggest_corrections(current_node, word, suggestions)

        return suggestions

    def _suggest_corrections(self, node, word, suggestions):
        if node.is_end_of_word:
            suggestions.append(word)

        for char, child_node in node.children.items():
            self._suggest_corrections(child_node, word + char, suggestions)

    def correct_sentence(self, sentence):
        corrected_sentence = []
        words = sentence.split()

        for word in words:
            suggestions = self.search_word(word)

            if suggestions:
                corrected_sentence.append(suggestions[0])
            else:
                corrected_sentence.append(word)

        return ' '.join(corrected_sentence)
```

