```python
class SegmentTreeNode:
    def __init__(self, start, end):
        self.start = start
        self.end = end
        self.count = 0
        self.left = None
        self.right = None

def build_segment_tree(nums, start, end):
    if start > end:
        return None

    node = SegmentTreeNode(start, end)

    if start == end:
        node.count = 0
    else:
        mid = (start + end) // 2
        node.left = build_segment_tree(nums, start, mid)
        node.right = build_segment_tree(nums, mid + 1, end)
        node.count = node.left.count + node.right.count

    return node

def update_segment_tree(node, index):
    if node.start == node.end:
        node.count += 1
        return

    mid = (node.start + node.end) // 2
    if index <= mid:
        update_segment_tree(node.left, index)
    else:
        update_segment_tree(node.right, index)

    node.count = node.left.count + node.right.count

def query_segment_tree(node, left, right):
    if node.start == left and node.end == right:
        return node.count

    mid = (node.start + node.end) // 2
    if right <= mid:
        return query_segment_tree(node.left, left, right)
    elif left > mid:
        return query_segment_tree(node.right, left, right)
    else:
        return query_segment_tree(node.left, left, mid) + query_segment_tree(node.right, mid + 1, right)

def max_subarrays_with_sum(nums, target):
    max_count = 0
    n = len(nums)
    st_root = build_segment_tree(nums, 0, n - 1)

    prefix_sum = 0
    for i in range(n):
        prefix_sum += nums[i]

        if prefix_sum <= target:
            max_count += 1

        max_count += query_segment_tree(st_root, 0, prefix_sum - target)
        update_segment_tree(st_root, prefix_sum)

    return max_count
```

The `build_segment_tree` function constructs the segment tree by recursively dividing the range into halves. Each node of the segment tree stores the count of elements within its range.

The `update_segment_tree` function updates the segment tree by incrementing the count of the appropriate node based on the index.

The `query_segment_tree` function returns the count of elements within a given range by recursively traversing the segment tree.

The `max_subarrays_with_sum` function takes an input list `nums` and a target value `target`. It initializes the maximum count to 0 and constructs the segment tree using `build_segment_tree`. It then iterates over the input list, keeping track of the prefix sum. If the prefix sum is less than or equal to the target, it increments the maximum count by 1. It also increments the maximum count by the count of subarrays whose sum is in the range `[prefix_sum - target, prefix_sum]` using `query_segment_tree`. Finally, it updates the segment tree using `update_segment_tree` with the current prefix sum. The function returns the maximum count.

You can use this code by calling the `max_subarrays_with_sum` function with your desired inputs, such as:

```python
nums = [2, 4, 1, 3, 5, 7, 8]
target = 10

result = max_subarrays_with_sum(nums, target)
print(f"Maximum number of subarrays with sum less than or equal to {target}: {result}")
```

