```python
class Queue:
    def __init__(self):
        self.items = []

    def is_empty(self):
        return len(self.items) == 0

    def enqueue(self, item):
        self.items.append(item)

    def dequeue(self):
        if not self.is_empty():
            return self.items.pop(0)
        else:
            return None

    def size(self):
        return len(self.items)

    def split_queue(self):
        if self.is_empty():
            return [], []

        midpoint = self.size() // 2

        # Create two new queues
        queue1 = Queue()
        queue2 = Queue()

        # Enqueue items to queue1
        for i in range(midpoint):
            item = self.dequeue()
            queue1.enqueue(item)

