            self.tree[tree_idx] = arr[start]
        else:
            mid = (start + end) // 2
            left_child_idx = 2*tree_idx + 1
            right_child_idx = 2*tree_idx + 2
            self.build(arr, left_child_idx, start, mid)
            self.build(arr, right_child_idx, mid+1, end)
            self.tree[tree_idx] = self.tree[left_child_idx] + self.tree[right_child_idx]

    def query(self, tree_idx, start, end, left, right):
        if start > right or end < left:
            return 0
        elif start >= left and end <= right:
            return self.tree[tree_idx]
        else:
            mid = (start + end) // 2
            left_child_idx = 2*tree_idx + 1
            right_child_idx = 2*tree_idx + 2
            left_sum = self.query(left_child_idx, start, mid, left, right)
            right_sum = self.query(right_child_idx, mid+1, end, left, right)
            return left_sum + right_sum

    def get_max_sum_submatrix(self, arr, left_row, right_row, left_col, right_col):
        m = len(arr)
        n = len(arr[0])
        prefix_sum = [[0] * (n+1) for _ in range(m+1)]

        for i in range(1, m+1):
            for j in range(1, n+1):
                prefix_sum[i][j] = arr[i-1][j-1] + prefix_sum[i-1][j] + prefix_sum[i][j-1] - prefix_sum[i-1][j-1]

        max_sum = float('-inf')
        for i in range(left_row, right_row+1):
            for j in range(left_col, right_col+1):
                for k in range(i, right_row+1):
                    for l in range(j, right_col+1):
                        sum_submatrix = prefix_sum[k+1][l+1] - prefix_sum[i][l+1] - prefix_sum[k+1][j] + prefix_sum[i][j]
                        max_sum = max(max_sum, sum_submatrix)

        return max_sum
