def chromatic_number(graph):
    """
    Determines the chromatic number of a graph.

    Args:
        graph (dict): A dictionary representing the graph where the keys are graph nodes and the values are sets of neighboring nodes.

    Returns:
        int: The minimum number of colors needed to color the graph such that no adjacent nodes have the same color.

    Raises:
        ValueError: If the graph is not valid or if it is not an undirected graph.

    """

    # Error checking and validation of the input graph
    if not graph or not isinstance(graph, dict):
        raise ValueError("Input graph is not valid.")

    for node in graph:
        if not isinstance(graph[node], set):
            raise ValueError("Invalid graph format. Neighbors of each node should be represented by a set.")

    # Backtracking recursive function to find the chromatic number
    def backtrack(node, colors):
        if node is None:
            return True

        for color in colors:
            if all(color not in colors[neighbor] for neighbor in graph[node]):
                colors[node] = color
                if backtrack(next_unassigned_node(node), colors):
                    return True
                colors[node] = None

        return False

    # Find the next unassigned node
    def next_unassigned_node(node):
        for neighbor in graph[node]:
            if colors[neighbor] is None:
                return neighbor
        return None

    # Initialize the colors dictionary with None for all nodes
    colors = {node: None for node in graph}

    # Starting from the first node, attempt to color the graph
    if backtrack(next_unassigned_node(list(graph.keys())[0]), colors):
        # Return the minimum number of colors needed
        return len(set(colors.values()))
    else:
        # If backtracking fails, the graph is not colorable
        raise ValueError("Graph is not colorable.")

