def is_prime(n):
    """Check if a number is prime.

    Args:
        n (int): The number to check.

    Returns:
        bool: True if the number is prime, False otherwise.
    """
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True


def sum_of_primes_in_queue(queue):
    """Calculate the sum of all prime numbers in a queue.

    Args:
        queue (Queue): The queue containing numbers.

    Returns:
        int: The sum of all prime numbers in the queue.
    """
    prime_sum = 0
    while not queue.is_empty():
        number = queue.dequeue()
        if is_prime(number):
            prime_sum += number
    return prime_sum
