    def __init__(self, items):
        self.items = items
        self.current_index = len(items) - 1

    def __iter__(self):
        return self

    def __next__(self):
        if self.current_index < 0:
            raise StopIteration
        item = self.items[self.current_index]
        self.current_index -= 1
        return item
