class SegmentTree:
    def __init__(self, n):
        self.n = n
        self.st = [0] * (4*n)

    def build(self, arr, v, tl, tr):
        if tl == tr:
            self.st[v] = arr[tl]
        else:
            tm = (tl + tr) // 2
            self.build(arr, v*2, tl, tm)
            self.build(arr, v*2+1, tm+1, tr)
            self.st[v] = self.st[v*2] + self.st[v*2+1]

    def query(self, v, tl, tr, l, r):
        if l > r:
            return 0
        if l == tl and r == tr:
            return self.st[v]
        tm = (tl + tr) // 2
        return self.query(v*2, tl, tm, l, min(r, tm)) + self.query(v*2+1, tm+1, tr, max(l, tm+1), r)

    def count_palindromic_substr(self, s, l, r):
        n = len(s)
        palindromes = [0] * n
        for i in range(n):
            p1 = i - 1
            p2 = i + 1
            count = 1
            while p1 >= 0 and p2 < n and s[p1] == s[p2]:
                count += 1
                p1 -= 1
                p2 += 1
            palindromes[i] = count

        self.build(palindromes, 1, 0, n-1)
        return self.query(1, 0, n-1, l, r)
