        Inserts a key into the AVL Tree.
        """
        self.root = self._insert_node(self.root, key)

    def _insert_node(self, node, key):
        """
        Helper function to recursively insert a node into the AVL Tree.
        """
        if node is None:
            return AVLTreeNode(key)

        if key < node.key:
            node.left = self._insert_node(node.left, key)
        elif key > node.key:
            node.right = self._insert_node(node.right, key)
        else:
            return node  # Duplicate keys are not allowed

        self._update_height(node)
        return self._rebalance(node, key)

    def delete(self, key):
