        Deletes a key from the AVL Tree.
        """
        self.root = self._delete_node(self.root, key)

    def _delete_node(self, root, key):
        """
        Helper function to recursively delete a node from the AVL Tree.
        """
        if root is None:
            return root

        if key < root.key:
            root.left = self._delete_node(root.left, key)

        elif key > root.key:
            root.right = self._delete_node(root.right, key)

        else:
            if root.left is None:
                temp = root.right
                root = None
                return temp

            elif root.right is None:
                temp = root.left
                root = None
                return temp

            temp = self._get_min_value_node(root.right)
            root.key = temp.key
            root.right = self._delete_node(root.right, temp.key)

        self._update_height(root)
        return self._rebalance(root, key)

    def _get_min_value_node(self, node):
