    def _search_key(self, node, key):
        """
        Helper function to recursively search for a key in the AVL Tree.
        """
        if node is None or node.key == key:
            return node

        if key < node.key:
            return self._search_key(node.left, key)

        return self._search_key(node.right, key)

    def _in_order_traversal(self, node):
        """
        Performs in-order traversal of the AVL Tree and returns a string representation.
        """
        if node is None:
            return ""

        return self._in_order_traversal(node.left) + str(node.key) + " " + self._in_order_traversal(node.right)
