            return None
        if len(alphabet) == 1:
            return WaveletNode(len(s))

        mid = len(alphabet) // 2
        left_alphabet = alphabet[:mid]
        right_alphabet = alphabet[mid:]

        left_s, right_s, bitmap = '', '', []
        for char in s:
            if char in left_alphabet:
                left_s += char
                right_s += '0'
                bitmap.append(0)
            else:
                left_s += '0'
                right_s += char
                bitmap.append(1)

        node = WaveletNode(len(s))
        node.left = self._build_wavelet_tree(left_s, left_alphabet)
        node.right = self._build_wavelet_tree(right_s, right_alphabet)
        node.bitmap = bitmap
        return node

    def count_palindrome_substrings(self, start, end):
        """
        Count the number of palindrome substrings within a given range.

        Parameters:
        - start (int): The starting index of the range (inclusive).
        - end (int): The ending index of the range (inclusive).

        Returns:
        - count (int): The number of palindrome substrings in the range.

        Raises:
        - ValueError: If the start or end index is out of bounds.
        """
        if start < 0 or start >= len(self.s):
            raise ValueError('Start index is out of bounds.')
        if end < 0 or end >= len(self.s):
            raise ValueError('End index is out of bounds.')
        if start > end:
            raise ValueError('Start index cannot be greater than end index.')

        return self._count_palindrome_substrings(self.tree, start, end, 0)

    def _count_palindrome_substrings(self, node, start, end, level):
        if node is None or start > end:
            return 0

        if start == end:
            return 1

        mid = (start + end) // 2
        left_count = self._count_char(node.left, start, mid, '1')
        right_count = self._count_char(node.right, start, mid, '0')

        if level % 2 == 0:
            count = left_count + right_count
        else:
            count = (end - start + 1) - (left_count + right_count)

        if mid < end:
            count += self._count_palindrome_substrings(node.left, mid + 1, end, level + 1)
            count += self._count_palindrome_substrings(node.right, mid + 1, end, level + 1)

        return count

    def _count_char(self, node, start, end, char):
        if node is None or start > end:
            return 0

        if start == end:
            return 1 if node.bitmap[start] == char else 0

        mid = (start + end) // 2
        if char == '0':
            return node.bitmap[mid] + self._count_char(node.left, start, mid, char)
        else:
            return node.bitmap[mid] + self._count_char(node.right, start, mid, char)


