class SegmentTree:
    def __init__(self, arr):
        self.arr = arr
        self.n = len(arr)
        self.tree = [0] * (2 * self.n)
        self.build(0, 0, self.n - 1)

    def build(self, node, start, end):
        if start == end:
            self.tree[node] = self.arr[start]
        else:
            mid = (start + end) // 2
            self.build(2 * node + 1, start, mid)
            self.build(2 * node + 2, mid + 1, end)
            self.tree[node] = self.tree[2 * node + 1] + self.tree[2 * node + 2]

    def query(self, node, start, end, left, right):
        if right < start or left > end:
            return float('inf')
        if left <= start and right >= end:
            return self.tree[node]
        mid = (start + end) // 2
        p1 = self.query(2 * node + 1, start, mid, left, right)
        p2 = self.query(2 * node + 2, mid + 1, end, left, right)
        return p1 + p2

    def find_subarray(self, value):
        return self.find_subarray_util(0, self.n - 1, value, 0)

    def find_subarray_util(self, left, right, value, index):
        if left == right:
            return left
        mid = (left + right) // 2
        subarray_sum = self.query(0, 0, self.n - 1, index, mid)
        if subarray_sum > value:
            return self.find_subarray_util(left, mid, value, index)
        else:
            return self.find_subarray_util(mid + 1, right, value, index + 1)


