def longest_path_dag(graph, source):
    """
    Find the longest path in a weighted directed acyclic graph (DAG) using topological sorting.

    Args:
        graph (dict): A dictionary representing the weighted directed acyclic graph (DAG).
                      The keys are the vertices, and the values are lists of tuples representing the
                      weighted edges. Each tuple consists of the target vertex and the weight of the edge.
        source: The source vertex from which to find the longest path.

    Returns:
        A tuple containing:
        - The length of the longest path from the source vertex to any other vertex in the graph
        - A dictionary with the longest path from the source vertex to each vertex

    """
    def topological_sort(vertex, visited, stack):
        visited[vertex] = True

        if vertex in graph:
            for edge in graph[vertex]:
                target_vertex = edge[0]
                if not visited[target_vertex]:
                    topological_sort(target_vertex, visited, stack)
        stack.append(vertex)

    def calculate_longest_path(source):
        longest_paths = {vertex: float('-inf') for vertex in graph}
        longest_paths[source] = 0

        while stack:
            vertex = stack.pop()
            if vertex in graph:
                for edge in graph[vertex]:
                    target_vertex = edge[0]
                    weight = edge[1]
                    if longest_paths[vertex] != float('-inf') and longest_paths[vertex] + weight > longest_paths[target_vertex]:
                        longest_paths[target_vertex] = longest_paths[vertex] + weight
        return longest_paths

    visited = {vertex: False for vertex in graph}
    stack = []

    for vertex in graph:
        if not visited[vertex]:
            topological_sort(vertex, visited, stack)

    return max(calculate_longest_path(source).values()), calculate_longest_path(source)
```

