class TrieNode:
    def __init__(self):
        self.children = {}  # Mapping from character to child TrieNode
        self.is_end_of_word = False
        self.frequency = 0  # Number of times the word appears in the Trie

    def add_word(self, word):
        """Add a word to the Trie."""
        node = self
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_end_of_word = True
        node.frequency += 1

    def find_most_frequent_word(self, prefix):
        """Find the most frequent word with a given prefix in the Trie."""
        node = self
        for char in prefix:
            if char not in node.children:
                return None  # Prefix is not present in the Trie
            node = node.children[char]

        return self._find_most_frequent_word_helper(node, prefix)

    def _find_most_frequent_word_helper(self, node, prefix):
        """Recursively find the most frequent word with the given prefix."""
        if node.is_end_of_word:
            max_word = prefix
        else:
            max_word = None

        for char, child in node.children.items():
            word = self._find_most_frequent_word_helper(child, prefix + char)
            if word:
                if not max_word or node.children[word[-1]].frequency > node.children[max_word[-1]].frequency:
                    max_word = word

        return max_word
```

