class SuffixNode:
    def __init__(self, start, end):
        self.start = start
        self.end = end
        self.children = {}

    def add_child(self, char, node):
        self.children[char] = node

    def get_child(self, char):
        return self.children.get(char)


class SuffixTree:
    def __init__(self, string):
        self.root = SuffixNode(-1, -1)
        self.string = string
        self.build_suffix_tree()

    def build_suffix_tree(self):
        for i in range(len(self.string)):
            self._build_suffix_tree_from_index(i)

    def _build_suffix_tree_from_index(self, index):
        current_node = self.root
        for j in range(index, len(self.string)):
            char = self.string[j]
            if char not in current_node.children:
                new_node = SuffixNode(j, len(self.string))
                current_node.add_child(char, new_node)
                return
            else:
                current_node = current_node.get_child(char)

    def get_longest_substring_length(self, k):
        def _get_substring_length(node, count):
            if count >= k:
                return node.end - node.start + 1
            else:
                longest_length = 0
                for child in node.children.values():
                    substring_length = _get_substring_length(child, count + 1)
                    longest_length = max(longest_length, substring_length)
                return longest_length

        return _get_substring_length(self.root, 0)


def find_longest_substring(string, k):
    suffix_tree = SuffixTree(string)
    return suffix_tree.get_longest_substring_length(k)
