def find_difference(sets):
    """
    Finds the difference between multiple sets.

    Args:
    - sets: A list of sets

    Returns:
    - The difference between the sets

    Example:
    >>> set1 = {1, 2, 3, 4, 5}
    >>> set2 = {3, 4, 5, 6, 7}
    >>> set3 = {5, 6, 7, 8, 9}
    >>> sets = [set1, set2, set3]
    >>> find_difference(sets)
    {1, 2}

    """
    if not sets:
        # If no sets are provided, return an empty set
        return set()

    # Start with the first set
    result = sets[0]

    # Loop through the remaining sets
    for s in sets[1:]:
        # Find the difference between the current set and the result set
        result = result.difference(s)

    return result
